-- ----------------------------
-- Table structure for vn_ward
-- ----------------------------
DROP TABLE IF EXISTS `vn_ward`;
CREATE TABLE `vn_ward`  (
  `id` varchar(6) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `type` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `provinceid` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `thu_tu` tinyint(4) NULL DEFAULT NULL,
  `active` tinyint(4) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

